{
  "county_id": "HVA16",
  "actions": [
    {
      "action_id": "timed-pathways",
      "action": "Proposed: Adopt national cancer-specific pathways with maximum times per step and a single fast-track referral from primary care, following the Danish and Swedish model.",
      "rationale": "The portfolio picks timed-pathways for HVA16 at EUR 284,211 a year, with a model scenario of 9.4 deaths postponed per year (range 1.4-18.9) and 94% of sensitivity runs keeping it, while the brief shows referral into specialist care is the earliest stage where the county is clearly worse than the country, with referrals processed within 3 days at 70.8% against 76.8% nationally.",
      "owner_role": "Accountable owner: Wellbeing services county, coordinated nationally by FICAN.",
      "indicator": "Indicator to monitor: Patients waiting over 6 months during the year for access to specialised health care per 10 000 inhabitants.",
      "roadmap_measure": "3.1.2"
    },
    {
      "action_id": "screening-reminders",
      "action": "Proposed: Send a second kit with plain-language, multilingual instructions to non-responders; measure the gain as a stepped pilot.",
      "rationale": "The brief shows colorectal screening participation in HVA16 is 75.6% against the 80% target, and the portfolio lists screening-reminders as the county screening action with an expected gain of 1.5-4.37 percentage points, closing about 69% of the gap.",
      "owner_role": "Accountable owner: Wellbeing services county screening unit.",
      "indicator": "Indicator to monitor: Proportion of invited to colorectal cancer screening who attended, %.",
      "roadmap_measure": "1.3.1"
    },
    {
      "action_id": "pathway-timestamps",
      "action": "Proposed: Add first contact, referral, diagnosis and first treatment dates, plus entry route, to the national cancer quality register and publish county-level medians quarterly.",
      "rationale": "The brief states this is the first step for every county because the Goal 3 indicator treatment within target times cannot be checked from open data, and time from referral to diagnosis and from diagnosis to first treatment is not published by county for any cancer.",
      "owner_role": "Accountable owner: FICAN with THL and the Finnish Cancer Registry.",
      "indicator": "Indicator to monitor: Share of new cancer cases with all four timestamps recorded.",
      "roadmap_measure": "3.2.1"
    }
  ],
  "evidence_does_not_support": "timed-pathways: Danish evidence is before/after without a control group. Patients left outside the pathway waited 4 days longer, so coverage must be monitored."
}

